def loss(self, trajectories, conditions):
    """
    Accepts the Batch(trajectories, conditions) namedtuple unpacked by Trainer.train_epoch().
    trajectories : [B, H, 6]  — concatenated [act(3D), obs(3D)]
    conditions   : {0: obs_seq[0],            # [B, 3] anchor for apply_conditioning
                    'primary_img': [B,3,H,W],
                    'wrist_img':   [B,3,H,W]}
    """
    if getattr(self.model, 'if_vision', True):
        # unsqueeze(1) → [B,1,3,H,W] as required by MultiImageObsEncoder window_size=1
        primary_img = conditions['primary_img'].unsqueeze(1)
        wrist_img   = conditions['wrist_img'].unsqueeze(1)
        obs_0       = conditions[0]                      # [B, 3]
        obs_seq     = trajectories[..., self.action_dim:]  # [B, H, 3]
        cond = {
            'visual': (primary_img, wrist_img, obs_seq),
            0: obs_0,
        }
    else:
        obs_0 = conditions[0]
        cond  = {0: obs_0}

    x = trajectories  # [B, H, 6]
    batch_size = x.shape[0]
    t = torch.randint(0, self.n_timesteps, (batch_size,), device=x.device).long()
    return self.p_losses(x, cond, t)

