import numpy as np
import scipy.interpolate as interpolate
import pdb

POINTMASS_KEYS = ['observations', 'actions', 'next_observations', 'deltas']

#-----------------------------------------------------------------------------#
#--------------------------- multi-field normalizer --------------------------#
#-----------------------------------------------------------------------------#

class DatasetNormalizer:

    def __init__(self, dataset, normalizer, path_lengths=None):
        dataset = flatten(dataset, path_lengths)

        self.observation_dim = dataset['observations'].shape[1]
        self.action_dim = dataset['actions'].shape[1]

        if type(normalizer) == str:
            normalizer = eval(normalizer)

        self.normalizers = {}
        for key, val in dataset.items():
            try:
                self.normalizers[key] = normalizer(val)
            except:
                print(f'[ utils/normalization ] Skipping {key} | {normalizer}')

    def __repr__(self):
        string = ''
        for key, normalizer in self.normalizers.items():
            string += f'{key}: {normalizer}]\n'
        return string

    def __call__(self, *args, **kwargs):
        return self.normalize(*args, **kwargs)

    def normalize(self, x, key):
        return self.normalizers[key].normalize(x)

    def unnormalize(self, x, key):
        return self.normalizers[key].unnormalize(x)

    def get_field_normalizers(self):
        return self.normalizers

def flatten(dataset, path_lengths):
    '''
        flattens dataset of { key: [ n_episodes x max_path_lenth x dim ] }
            to { key : [ (n_episodes * sum(path_lengths)) x dim ]}
    '''
    flattened = {}
    for key, xs in dataset.items():
        assert len(xs) == len(path_lengths)
        flattened[key] = np.concatenate([
            x[:length]
            for x, length in zip(xs, path_lengths)
        ], axis=0)
    return flattened

#-----------------------------------------------------------------------------#
#------------------------------- @TODO: remove? ------------------------------#
#-----------------------------------------------------------------------------#

class PointMassDatasetNormalizer(DatasetNormalizer):

    def __init__(self, preprocess_fns, dataset, normalizer, keys=POINTMASS_KEYS):

        reshaped = {}
        for key, val in dataset.items():
            dim = val.shape[-1]
            reshaped[key] = val.reshape(-1, dim)

        self.observation_dim = reshaped['observations'].shape[1]
        self.action_dim = reshaped['actions'].shape[1]

        if type(normalizer) == str:
            normalizer = eval(normalizer)

        self.normalizers = {

        self.normalizers = {
            key: normalizer(reshaped[key])
            for key in keys
        }

#-----------------------------------------------------------------------------#
#-------------------------- single-field normalizers -------------------------#
#-----------------------------------------------------------------------------#

class Normalizer:
    '''
        parent class, subclass by defining the `normalize` and `unnormalize` methods
    '''

    def __init__(self, X):
        self.X = X.astype(np.float32)
        self.mins = X.min(axis=0)
        self.maxs = X.max(axis=0)

    def __repr__(self):
        return (
            f'''[ Normalizer ] dim: {self.mins.size}\n    -: '''
            f'''{np.round(self.mins, 2)}\n    +: {np.round(self.maxs, 2)}\n'''
        )

    def __call__(self, x):
        return self.normalize(x)

    def normalize(self, *args, **kwargs):
        raise NotImplementedError()

    def unnormalize(self, *args, **kwargs):
        raise NotImplementedError()


class DebugNormalizer(Normalizer):
    '''
        identity function
    '''

    def normalize(self, x, *args, **kwargs):
        return x

    def unnormalize(self, x, *args, **kwargs):
        return x


class GaussianNormalizer(Normalizer):
    '''
        normalizes to zero mean and unit variance
    '''

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.means = self.X.mean(axis=0)
        self.stds = self.X.std(axis=0)
        self.z = 1

    def __repr__(self):
        return (
            f'''[ Normalizer ] dim: {self.mins.size}\n    '''
            f'''means: {np.round(self.means, 2)}\n    '''
            f'''stds: {np.round(self.z * self.stds, 2)}\n'''
        )

    def normalize(self, x):
        return (x - self.means) / self.stds

    def unnormalize(self, x):
        return x * self.stds + self.means


class LimitsNormalizer(Normalizer):
    '''
        maps [ xmin, xmax ] to [ -1, 1 ]
    '''

    def normalize(self, x):
        ## [ 0, 1 ]
        x = (x - self.mins) / (self.maxs - self.mins)
        ## [ -1, 1 ]
        x = 2 * x - 1
        return x

    def unnormalize(self, x, eps=1e-4):
        '''
            x : [ -1, 1 ]
        '''
        if x.max() > 1 + eps or x.min() < -1 - eps:
            # print(f'[ datasets/mujoco ] Warning: sample out of range | ({x.min():.4f}, {x.max():.4f})')
            x = np.clip(x, -1, 1)

        ## [ -1, 1 ] --> [ 0, 1 ]
        x = (x + 1) / 2.

        return x * (self.maxs - self.mins) + self.mins

class SafeLimitsNormalizer(LimitsNormalizer):
    '''
        functions like LimitsNormalizer, but can handle data for which a dimension is constant
    '''

    def __init__(self, *args, eps=1, **kwargs):
        super().__init__(*args, **kwargs)
        for i in range(len(self.mins)):
            if self.mins[i] == self.maxs[i]:
                print(f'''
                    [ utils/normalization ] Constant data in dimension {i} | '''
                    f'''max = min = {self.maxs[i]}'''
                )
                self.mins -= eps
                self.maxs += eps

#-----------------------------------------------------------------------------#
#------------------------------- CDF normalizer ------------------------------#
#-----------------------------------------------------------------------------#

class CDFNormalizer(Normalizer):
    '''
        makes training data uniform (over each dimension) by transforming it with marginal CDFs

            nn.Mish(),
        )

    def forward(self, x):
        return self.block(x)

#-----------------------------------------------------------------------------#
#--------------------------------- attention ---------------------------------#
#-----------------------------------------------------------------------------#

class Residual(nn.Module):
    def __init__(self, fn):
        super().__init__()
        self.fn = fn

    def forward(self, x, *args, **kwargs):
        return self.fn(x, *args, **kwargs) + x

class LayerNorm(nn.Module):
    def __init__(self, dim, eps = 1e-5):
        super().__init__()
        self.eps = eps
        self.g = nn.Parameter(torch.ones(1, dim, 1))
        self.b = nn.Parameter(torch.zeros(1, dim, 1))

    def forward(self, x):
        var = torch.var(x, dim=1, unbiased=False, keepdim=True)
        mean = torch.mean(x, dim=1, keepdim=True)
        return (x - mean) / (var + self.eps).sqrt() * self.g + self.b

class PreNorm(nn.Module):
    def __init__(self, dim, fn):
        super().__init__()
        self.fn = fn
        self.norm = LayerNorm(dim)

    def forward(self, x):
        x = self.norm(x)
        return self.fn(x)

    ## set loss coefficients for dimensions of observation
    if weights_dict is None: weights_dict = {}
    for ind, w in weights_dict.items():
        dim_weights[self.action_dim + ind] *= w

    ## decay loss with trajectory timestep: discount**t
    discounts = discount ** torch.arange(self.horizon, dtype=torch.float)
    discounts = discounts / discounts.mean()
    loss_weights = torch.einsum('h,t->ht', discounts, dim_weights)

    ## manually set a0 weight
    loss_weights[0, :self.action_dim] = action_weight
    return loss_weights

#------------------------------------------ sampling ------------------------------------------#

def predict_start_from_noise(self, x_t, t, noise):
    '''
        if self.predict_epsilon, model output is (scaled) noise;
        otherwise, model predicts x0 directly
    '''
    if self.predict_epsilon:
        return (
            extract(self.sqrt_recip_alphas_cumprod, t, x_t.shape) * x_t -
            extract(self.sqrt_recipm1_alphas_cumprod, t, x_t.shape) * noise
        )
    else:
        return noise

def q_posterior(self, x_start, x_t, t):
    posterior_mean = (
        extract(self.posterior_mean_coef1, t, x_t.shape) * x_start +
        extract(self.posterior_mean_coef2, t, x_t.shape) * x_t
    )
    posterior_variance = extract(self.posterior_variance, t, x_t.shape)
    posterior_log_variance_clipped = extract(self.posterior_log_variance_clipped, t, x_t.shape)
    return posterior_mean, posterior_variance, posterior_log_variance_clipped

def p_mean_variance(self, x, cond, t, returns=None, projector=None, constraints=None):
    # if self.model.calc_energy:
    #     assert self.predict_epsilon
    #     x = torch.tensor(x, requires_grad=True)
    #     t = torch.tensor(t, dtype=torch.float, requires_grad=True)
    #     returns = torch.tensor(returns, requires_grad=True)

    if self.returns_condition:
        # epsilon could be epsilon or x0 itself
        epsilon_cond = self.model(x, cond, t, returns, use_dropout=False)
        epsilon_uncond = self.model(x, cond, t, returns, force_dropout=True)
        epsilon = epsilon_uncond + self.condition_guidance_w*(epsilon_cond - epsilon_uncond)
    else:
        epsilon = self.model(x, cond, t)

    t = t.detach().to(torch.int64)
    x_recon = self.predict_start_from_noise(x, t=t, noise=epsilon)

    if self.clip_denoised:
        x_recon.clamp_(-1., 1.)
    else:
        assert RuntimeError()

    model_mean, posterior_variance, posterior_log_variance = self.q_posterior(
            x_start=x_recon, x_t=x, t=t)

    if projector is not None and projector.gradient:
        if self.goal_dim > 0:
            grad = projector.compute_gradient(x_recon[:,:,:-self.goal_dim], constraints)
        else:
            grad = projector.compute_gradient(x_recon, constraints)
        model_mean = model_mean + grad

    return model_mean, posterior_variance, posterior_log_variance

@torch.no_grad()
def p_sample(self, x, cond, t, returns=None, projector=None, constraints=None):
    b, *_, device = *x.shape, x.device
    model_mean, _, model_log_variance = self.p_mean_variance(x=x, cond=cond, t=t, returns=returns, projector=projector, constraints=constraints)
    noise = 0.5*torch.randn_like(x)
    # no noise when t == 0
    nonzero_mask = (1 - (t == 0).float()).reshape(b, *((1,) * (len(x.shape) - 1)))
    return model_mean + nonzero_mask * (0.5 * model_log_variance).exp() * noise

@torch.no_grad()
def p_sample_loop(self, shape, cond, returns=None, return_diffusion=False, projector=None, constraints=None, repeat_last=0):
    device = self.betas.device

    batch_size = shape[0]
    x = 0.5*torch.randn(shape, device=device)
    x = apply_conditioning(x, cond, self.action_dim, goal_dim=self.goal_dim)

    if return_diffusion: diffusion = [x]
    costs = {}

    # Denoising process
    last_timestep = -repeat_last if repeat_last > 0 and projector is not None else 0
    for i in reversed(range(last_timestep, self.n_timesteps)):
        t = i if i >= 0 else 0
        timesteps = torch.full((batch_size,), t, device=device, dtype=torch.long)
        if projector is not None and projector.gradient and t <= projector.diffusion_timestep_threshold * self.n_timesteps:
            x = self.p_sample(x, cond, timesteps, returns, projector=projector, constraints=constraints)
        else:
            x = self.p_sample(x, cond, timesteps, returns)

        x = apply_conditioning(x, cond, self.action_dim, goal_dim=self.goal_dim)

        if projector is not None and not projector.gradient and t <= projector.diffusion_timestep_threshold * self.n_timesteps:
            if self.goal_dim > 0:
                x[:,:,:-self.goal_dim], projection_costs = projector.project(x[:,:,:-self.goal_dim], constraints)
                costs[i] = projection_costs
            else:
                x, projection_costs = projector.project(x, constraints)
                costs[i] = projection_costs

        x = apply_conditioning(x, cond, self.action_dim, goal_dim=self.goal_dim)

        if return_diffusion: diffusion.append(x)

    infos = {}
    if return_diffusion: infos['diffusion'] = torch.stack(diffusion, dim=1)
    infos['projection_costs'] = costs

    return x, infos

@torch.no_grad()
def conditional_sample(self, cond, returns=None, horizon=None, *args, **kwargs):
    '''
        conditions : [ (time, state), ... ]
    '''
    device = self.betas.device
    batch_size = len(cond[0])
    horizon = horizon or self.horizon
    shape = (batch_size, horizon, self.transition_dim)

    return self.p_sample_loop(shape, cond, returns, *args, **kwargs)

def grad_p_sample(self, x, cond, t, returns=None):
    b, *_, device = *x.shape, x.device
    model_mean, _, model_log_variance = self.p_mean_variance(x=x, cond=cond, t=t, returns=returns)
    noise = 0.5*torch.randn_like(x)
    # no noise when t == 0
    nonzero_mask = (1 - (t == 0).float()).reshape(b, *((1,) * (len(x.shape) - 1)))
    return model_mean + nonzero_mask * (0.5 * model_log_variance).exp() * noise

def grad_p_sample_loop(self, shape, cond, returns=None, verbose=True, return_diffusion=False):
    device = self.betas.device

    batch_size = shape[0]
    x = 0.5*torch.randn(shape, device=device)
    x = apply_conditioning(x, cond, self.action_dim, goal_dim=self.goal_dim)

    if return_diffusion: diffusion = [x]

    # progress = utils.Progress(self.n_timesteps) if verbose else utils.Silent()
    for i in reversed(range(0, self.n_timesteps)):
        timesteps = torch.full((batch_size,), i, device=device, dtype=torch.long)
        x = self.grad_p_sample(x, cond, timesteps, returns)
        x = apply_conditioning(x, cond, self.action_dim, goal_dim=self.goal_dim)

        # progress.update({'t': i})

        if return_diffusion: diffusion.append(x)

    # progress.close()

    if return_diffusion:
        return x, torch.stack(diffusion, dim=1)
    else:
        return x

def grad_conditional_sample(self, cond, returns=None, horizon=None, *args, **kwargs):
    '''
        conditions : [ (time, state), ... ]
    '''
    device = self.betas.device
    batch_size = len(cond[0])
    horizon = horizon or self.horizon
    shape = (batch_size, horizon, self.transition_dim)

    return self.grad_p_sample_loop(shape, cond, returns, *args, **kwargs)

#------------------------------------------ training ------------------------------------------#

def q_sample(self, x_start, t, noise=None):
    if noise is None:
        noise = torch.randn_like(x_start)

    sample = (
        extract(self.sqrt_alphas_cumprod, t, x_start.shape) * x_start +
        extract(self.sqrt_one_minus_alphas_cumprod, t, x_start.shape) * noise
    )

    return sample

def p_losses(self, x_start, cond, t, returns=None):
    noise = torch.randn_like(x_start)

    if self.predict_epsilon:
        # Cause we condition on obs at t=0
        # noise[:, 0, self.action_dim:] = 0

def p_losses(self, x_start, cond, t, returns=None):
    noise = torch.randn_like(x_start)

    if self.predict_epsilon:
        # Cause we condition on obs at t=0
        # noise[:, 0, self.action_dim:] = 0
        noise = apply_conditioning(noise, cond, self.action_dim, goal_dim=self.goal_dim, noise=True)

    x_noisy = self.q_sample(x_start=x_start, t=t, noise=noise)
    x_noisy = apply_conditioning(x_noisy, cond, self.action_dim, goal_dim=self.goal_dim)

    x_recon = self.model(x_noisy, cond, t, returns)

    if not self.predict_epsilon:
        x_recon = apply_conditioning(x_recon, cond, self.action_dim, goal_dim=self.goal_dim)

    assert noise.shape == x_recon.shape

    if self.predict_epsilon:
        loss, info = self.loss_fn(x_recon, noise)
    else:
        loss, info = self.loss_fn(x_recon, x_start)

    return loss, info

def loss(self, x, cond, returns=None):
    batch_size = len(x)
    t = torch.randint(0, self.n_timesteps, (batch_size,), device=x.device).long()
    return self.p_losses(x, cond, t, returns)

def forward(self, cond, *args, **kwargs):
    return self.conditional_sample(cond=cond, *args, **kwargs)

    self.device = train_device

def reset_parameters(self):
    self.ema_model.load_state_dict(self.model.state_dict())

def step_ema(self):
    if self.step < self.step_start_ema:
        self.reset_parameters()
        return
    self.ema.update_model_average(self.ema_model, self.model)

#-----------------------------------------------------------------------------#
#------------------------------------ api ------------------------------------#
#-----------------------------------------------------------------------------#

def train_epoch(self, n_train_steps, epoch=0):        
    progress_bar = tqdm(total=n_train_steps, mininterval=1e10)
    progress_bar.set_description(f"Epoch {epoch}")

    for step in range(n_train_steps):
        for _ in range(self.gradient_accumulate_every):
            batch = next(self.train_dataloader)
            batch = batch_to_device(batch, device=self.device)
            loss, infos = self.model.loss(*batch)
            loss = loss / self.gradient_accumulate_every
            loss.backward()

        self.optimizer.step()
        self.lr_scheduler.step()
        self.optimizer.zero_grad()

        if self.step % self.update_ema_every == 0:
            self.step_ema()

        if self.step % self.save_freq == 0:
            label = self.step
            self.save(label)

        if self.step % self.log_freq == 0:
            self.train_losses.append([self.step, loss.item()])
            if 'a0_loss' in infos:
                self.train_a0_losses.append([self.step, infos['a0_loss'].item()])

            if self.train_test_split < 1:
                test_loss, test_a0_loss = self.test()
                self.test_losses.append([self.step, test_loss])
                self.test_a0_losses.append([self.step, test_a0_loss])
                if test_loss < self.best_test_loss:
                    self.best_test_loss = test_loss
                    self.save_best()
                if self.step == 0:
                    # if self.model.action_dim > 0:
                    print(f'Initial test loss: {test_loss:8.4f}, a0 loss: {test_a0_loss:8.4f}')
                    # else:
                        # print(f'Initial test loss: {test_loss:8.4f}')
            self.save_losses()

        # if self.train_test_split < 1:
        #     if 'a0_loss' in infos:
        #         logs = {"loss": loss.item(), "a0_loss": infos['a0_loss'].item(), "loss_test": test_loss, "a0_loss_test": test_a0_loss, "lr": self.lr_scheduler.get_last_lr()[0], "step": self.step}
        #     else:
        #         logs = {"loss": loss.item(), "loss_test": test_loss, "lr": self.lr_scheduler.get_last_lr()[0], "step": self.step}
        # else:
        #     if 'a0_loss' in infos:
        #         logs = {"loss": loss.item(), "a0_loss": infos['a0_loss'].item(), "lr": self.lr_scheduler.get_last_lr()[0], "step": self.step}
        #     else:
        #         logs = {"loss": loss.item(), "lr": self.lr_scheduler.get_last_lr()[0], "step": self.step}

        logs = {"loss": loss.item()}
        for l in ["diffusion_loss", "dyn_loss", "a0_loss", ]:
            if l in infos:
                logs[l] = infos[l].item()
        if self.train_test_split < 1:
            logs["loss_test"] = test_loss
            if 'a0_loss' in infos:
                logs["a0_loss_test"] = test_a0_loss
        logs["lr"] = self.lr_scheduler.get_last_lr()[0]
        logs["step"] = self.step

def forward(self, cond, *args, **kwargs):
    """
    Closed-loop inference entry point.

    Expected cond format from VisualAgentWrapper:
        cond = {0: (bp_image_seq, inhand_image_seq, obs_6d_seq)}
    where each is (B, window_size, ...).

    Transforms to the internal format used by p_sample_loop:
        {0: obs_6d_at_last_step,   ← snapping anchor
         'visual': (bp_imgs, inhand_imgs, obs_6d_seq)}
    """
    if isinstance(cond, dict) and 0 in cond and isinstance(cond[0], tuple):
        bp_imgs, inhand_imgs, obs_seq = cond[0]
        # obs_seq: (B, window_size, 6)
        # Use the most recent obs as the apply_conditioning anchor
        snap_obs = obs_seq[:, -1]   # (B, 6)
        new_cond = {
            0:        snap_obs,
            'visual': (bp_imgs, inhand_imgs, obs_seq),
        }
    else:
        new_cond = cond

    return super().forward(new_cond, *args, **kwargs)

def p_losses(self, x_start, cond, t, returns=None):
    noise = torch.randn_like(x_start)

    if self.predict_epsilon:
        # Cause we condition on obs at t=0
        # noise[:, 0, self.action_dim:] = 0
        noise = apply_conditioning(noise, cond, self.action_dim, goal_dim=self.goal_dim, noise=True)

    x_noisy = self.q_sample(x_start=x_start, t=t, noise=noise)
    x_noisy = apply_conditioning(x_noisy, cond, self.action_dim, goal_dim=self.goal_dim)

    x_recon = self.model(x_noisy, cond, t, returns)

    if not self.predict_epsilon:
        x_recon = apply_conditioning(x_recon, cond, self.action_dim, goal_dim=self.goal_dim)

    assert noise.shape == x_recon.shape

    if self.predict_epsilon:
        loss, info = self.loss_fn(x_recon, noise)
    else:
        loss, info = self.loss_fn(x_recon, x_start)

    return loss, info

def loss(self, x, cond, returns=None):
    batch_size = len(x)
    t = torch.randint(0, self.n_timesteps, (batch_size,), device=x.device).long()
    return self.p_losses(x, cond, t, returns)

def forward(self, cond, *args, **kwargs):
    return self.conditional_sample(cond=cond, *args, **kwargs)

import numpy as np
import scipy.interpolate as interpolate
import pdb

POINTMASS_KEYS = ['observations', 'actions', 'next_observations', 'deltas']

#-----------------------------------------------------------------------------#
#--------------------------- multi-field normalizer --------------------------#
#-----------------------------------------------------------------------------#

class DatasetNormalizer:

    def __init__(self, dataset, normalizer, path_lengths=None):
        dataset = flatten(dataset, path_lengths)

        self.observation_dim = dataset['observations'].shape[1]
        self.action_dim = dataset['actions'].shape[1]

        if type(normalizer) == str:
            normalizer = eval(normalizer)

        self.normalizers = {}
        for key, val in dataset.items():
            try:
                self.normalizers[key] = normalizer(val)
            except:
                print(f'[ utils/normalization ] Skipping {key} | {normalizer}')

    def __repr__(self):
        string = ''
        for key, normalizer in self.normalizers.items():
            string += f'{key}: {normalizer}]\n'
        return string

    def __call__(self, *args, **kwargs):
        return self.normalize(*args, **kwargs)

    def normalize(self, x, key):
        return self.normalizers[key].normalize(x)

    def unnormalize(self, x, key):
        return self.normalizers[key].unnormalize(x)

    def get_field_normalizers(self):
        return self.normalizers

def flatten(dataset, path_lengths):
    '''
        flattens dataset of { key: [ n_episodes x max_path_lenth x dim ] }
            to { key : [ (n_episodes * sum(path_lengths)) x dim ]}
    '''
    flattened = {}
    for key, xs in dataset.items():
        assert len(xs) == len(path_lengths)
        flattened[key] = np.concatenate([
            x[:length]
            for x, length in zip(xs, path_lengths)
        ], axis=0)
    return flattened

#-----------------------------------------------------------------------------#
#------------------------------- @TODO: remove? ------------------------------#
#-----------------------------------------------------------------------------#

class PointMassDatasetNormalizer(DatasetNormalizer):

    def __init__(self, preprocess_fns, dataset, normalizer, keys=POINTMASS_KEYS):

        reshaped = {}
        for key, val in dataset.items():
            dim = val.shape[-1]
            reshaped[key] = val.reshape(-1, dim)

        self.observation_dim = reshaped['observations'].shape[1]
        self.action_dim = reshaped['actions'].shape[1]

        if type(normalizer) == str:
            normalizer = eval(normalizer)

        self.normalizers = {
            key: normalizer(reshaped[key])
            for key in keys
        }

#-----------------------------------------------------------------------------#
#-------------------------- single-field normalizers -------------------------#
#-----------------------------------------------------------------------------#

class Normalizer:
    '''
        parent class, subclass by defining the `normalize` and `unnormalize` methods
    '''

    def __init__(self, X):
        self.X = X.astype(np.float32)
        self.mins = X.min(axis=0)
        self.maxs = X.max(axis=0)

    def __repr__(self):
        return (
            f'''[ Normalizer ] dim: {self.mins.size}\n    -: '''
            f'''{np.round(self.mins, 2)}\n    +: {np.round(self.maxs, 2)}\n'''
        )

    def __call__(self, x):
        return self.normalize(x)

    def normalize(self, *args, **kwargs):
        raise NotImplementedError()

    def unnormalize(self, *args, **kwargs):
        raise NotImplementedError()


class DebugNormalizer(Normalizer):
    '''
        identity function
    '''

    def normalize(self, x, *args, **kwargs):
        return x

    def unnormalize(self, x, *args, **kwargs):
        return x


class GaussianNormalizer(Normalizer):
    '''
        normalizes to zero mean and unit variance
    '''

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.means = self.X.mean(axis=0)
        self.stds = self.X.std(axis=0)
        self.z = 1

    def __repr__(self):
        return (
            f'''[ Normalizer ] dim: {self.mins.size}\n    '''
            f'''means: {np.round(self.means, 2)}\n    '''
            f'''stds: {np.round(self.z * self.stds, 2)}\n'''
        )

    def normalize(self, x):
        return (x - self.means) / self.stds

    def unnormalize(self, x):
        return x * self.stds + self.means


class LimitsNormalizer(Normalizer):
    '''
        maps [ xmin, xmax ] to [ -1, 1 ]
    '''

    def normalize(self, x):
        ## [ 0, 1 ]
        x = (x - self.mins) / (self.maxs - self.mins)
        ## [ -1, 1 ]
        x = 2 * x - 1
        return x

    def unnormalize(self, x, eps=1e-4):
        '''
            x : [ -1, 1 ]
        '''
        if x.max() > 1 + eps or x.min() < -1 - eps:
            # print(f'[ datasets/mujoco ] Warning: sample out of range | ({x.min():.4f}, {x.max():.4f})')
            x = np.clip(x, -1, 1)

        ## [ -1, 1 ] --> [ 0, 1 ]
        x = (x + 1) / 2.

        return x * (self.maxs - self.mins) + self.mins

class SafeLimitsNormalizer(LimitsNormalizer):
    '''
        functions like LimitsNormalizer, but can handle data for which a dimension is constant
    '''

    def __init__(self, *args, eps=1, **kwargs):
        super().__init__(*args, **kwargs)
        for i in range(len(self.mins)):
            if self.mins[i] == self.maxs[i]:
                print(f'''
                    [ utils/normalization ] Constant data in dimension {i} | '''
                    f'''max = min = {self.maxs[i]}'''
                )
                self.mins -= eps
                self.maxs += eps

#-----------------------------------------------------------------------------#
#------------------------------- CDF normalizer ------------------------------#
#-----------------------------------------------------------------------------#

class CDFNormalizer(Normalizer):
    '''
        makes training data uniform (over each dimension) by transforming it with marginal CDFs
    '''

    def __init__(self, X):
        super().__init__(atleast_2d(X))
        self.dim = self.X.shape[1]
        self.cdfs = [
            CDFNormalizer1d(self.X[:, i])
            for i in range(self.dim)
        ]

    def __repr__(self):
        return f'[ CDFNormalizer ] dim: {self.mins.size}\n' + '    |    '.join(
            f'{i:3d}: {cdf}' for i, cdf in enumerate(self.cdfs)
        )

    def wrap(self, fn_name, x):
        shape = x.shape
        ## reshape to 2d
        x = x.reshape(-1, self.dim)
        out = np.zeros_like(x)
        for i, cdf in enumerate(self.cdfs):
            fn = getattr(cdf, fn_name)
            out[:, i] = fn(x[:, i])
        return out.reshape(shape)

    def normalize(self, x):
        return self.wrap('normalize', x)

    def unnormalize(self, x):
        return self.wrap('unnormalize', x)

class CDFNormalizer1d:
    '''
        CDF normalizer for a single dimension
    '''

    def __init__(self, X):
        assert X.ndim == 1
        self.X = X.astype(np.float32)
        quantiles, cumprob = empirical_cdf(self.X)
        self.fn = interpolate.interp1d(quantiles, cumprob)
        self.inv = interpolate.interp1d(cumprob, quantiles)

        self.xmin, self.xmax = quantiles.min(), quantiles.max()
        self.ymin, self.ymax = cumprob.min(), cumprob.max()

    def __repr__(self):
        return (
            f'[{np.round(self.xmin, 2):.4f}, {np.round(self.xmax, 2):.4f}'
        )

    def normalize(self, x):
        x = np.clip(x, self.xmin, self.xmax)
        ## [ 0, 1 ]
        y = self.fn(x)
        ## [ -1, 1 ]
        y = 2 * y - 1
        return y

    def unnormalize(self, x, eps=1e-4):
        '''
            X : [ -1, 1 ]
        '''
        ## [ -1, 1 ] --> [ 0, 1 ]
        x = (x + 1) / 2.

        if (x < self.ymin - eps).any() or (x > self.ymax + eps).any():
            print(
                f'''[ dataset/normalization ] Warning: out of range in unnormalize: '''
                f'''[{x.min()}, {x.max()}] | '''
                f'''x : [{self.xmin}, {self.xmax}] | '''
                f'''y: [{self.ymin}, {self.ymax}]'''
            )

        x = np.clip(x, self.ymin, self.ymax)

        y = self.inv(x)
        return y

def empirical_cdf(sample):
    ## https://stackoverflow.com/a/33346366

    # find the unique values and their corresponding counts
    quantiles, counts = np.unique(sample, return_counts=True)

    # take the cumulative sum of the counts and divide by the sample size to
    # get the cumulative probabilities between 0 and 1
    cumprob = np.cumsum(counts).astype(np.double) / sample.size

    return quantiles, cumprob

def atleast_2d(x):
    if x.ndim < 2:
        x = x[:,None]
    return x

import os
from collections.abc import Mapping
import importlib
import pickle

def import_class(_class):
    if type(_class) is not str: return _class
    ## 'diffusion' on standard installs
    repo_name = __name__.split('.')[0]
    ## eg, 'utils'
    module_name = '.'.join(_class.split('.')[:-1])
    ## eg, 'Renderer'
    class_name = _class.split('.')[-1]
    ## eg, 'diffusion.utils'
    module = importlib.import_module(f'{repo_name}.{module_name}')
    ## eg, diffusion.utils.Renderer
    _class = getattr(module, class_name)
    # print(f'[ utils/config ] Imported {repo_name}.{module_name}:{class_name}')
    return _class

class Config(Mapping):

    def __init__(self, _class, verbose=True, savepath=None, device=None, **kwargs):
        self._class = import_class(_class)
        self._device = device
        self._dict = {}

        for key, val in kwargs.items():
            self._dict[key] = val

        if verbose:
            print(self)

        if savepath is not None:
            savepath = os.path.join(*savepath) if type(savepath) is tuple else savepath
            if not os.path.exists(savepath):
                pickle.dump(self, open(savepath, 'wb'))
                print(f'[ utils/config ] Saved config to: {savepath}\n')

            # Also save as JSON for better robustness/readability
            json_base = savepath.replace('.pkl', '')
            final_json_path = f'{json_base}.json'

            # If primary json already exists, we are resuming/re-running.
            # Preserve the original and save the current as a numbered version.
            if os.path.exists(final_json_path):
                resume_idx = 1
                while os.path.exists(f'{json_base}_resume_{resume_idx}.json'):
                    resume_idx += 1
                final_json_path = f'{json_base}_resume_{resume_idx}.json'

            try:
                import json
                def default_json(obj):
                    if hasattr(obj, '__name__'): return obj.__name__
                    return str(obj)

                with open(final_json_path, 'w') as f:
                    json.dump({
                        '_class': self._class.__name__,
                        **self._dict
                    }, f, indent=4, default=default_json)
                print(f'[ utils/config ] Saved config to: {final_json_path}\n')
            except Exception:
                pass

    def __repr__(self):
        string = f'\n[utils/config ] Config: {self._class}\n'
        for key in sorted(self._dict.keys()):
            val = self._dict[key]
            string += f'    {key}: {val}\n'
        return string

    def __iter__(self):
        return iter(self._dict)

    def __getitem__(self, item):
        return self._dict[item]

    def __len__(self):
        return len(self._dict)

    def __getattr__(self, attr):
        if attr == '_dict' and '_dict' not in vars(self):
            self._dict = {}
            return self._dict
        try:
            return self._dict[attr]
        except KeyError:
            raise AttributeError(attr)

    def __call__(self, *args, **kwargs):
        instance = self._class(*args, **kwargs, **self._dict)
        if self._device:
            instance = instance.to(self._device)
        return instance

